/// Shorten to `budget`, dropping the MIDDLE rather than the tail.
///
/// THE DISTINGUISHING PART OF A SHELL COMMAND IS AT THE END. This used to keep the first 80
/// characters, and a fleet worktree path is about ninety-five — so every `cd <path> && <verb>`
/// rendered as the same truncated `cd /home/.../twitt`. Measured on the twitter-clone-test director:
/// six DIFFERENT commands, with results of 180, 384, 151, 461, 109 and 109 bytes, all printed
/// identically, while the model itself reported "I've been running the same command repeatedly".
/// Keeping the head is exactly the wrong half.
///
/// The head still earns a quarter of the budget: it carries the verb (`cd`, `git`, `npm`), which
/// orients the reader before the tail tells them which invocation it was.
pub fn elide_middle(s: &str, budget: usize) -> String {
    let chars: Vec<char> = s.chars().collect();
    if chars.len() <= budget {
        return s.to_string();
    }
    // A budget too small to hold both ends plus the marker degrades to the TAIL, which is the half
    // worth keeping.
    let head = budget / 4;
    let tail = budget.saturating_sub(head + 1);
    let head_s: String = chars[..head.min(chars.len())].iter().collect();
    let tail_s: String = chars[chars.len().saturating_sub(tail)..].iter().collect();
    format!("{head_s}\u{2026}{tail_s}")
}
